"""Mirror the repo into a scratch copy without unreadable special files (the sandbox's masks)."""
import os, shutil, stat, sys
from pathlib import Path
src, dst = Path(sys.argv[1]), Path(sys.argv[2])
skip_dirs = {".git", "framework", ".pytest_cache", "__pycache__", "sdlc_framework.egg-info"}
for dirpath, dirnames, filenames in os.walk(src):
    rel = Path(dirpath).relative_to(src)
    dirnames[:] = [d for d in dirnames if d not in skip_dirs and not (Path(dirpath)/d).is_char_device()]
    (dst / rel).mkdir(parents=True, exist_ok=True)
    for f in filenames:
        p = Path(dirpath) / f
        try:
            if not stat.S_ISREG(p.lstat().st_mode):
                continue
            t = dst / rel / f
            if not t.exists() or t.stat().st_mtime < p.stat().st_mtime or t.stat().st_size != p.stat().st_size:
                shutil.copy2(p, t)
        except OSError:
            pass
